4	
5	import api from '../../services/api';
6	
7	import logoImage from '../../assets/logo.svg';
8	import Footer from '../../components/Footer';
9	
10	import { Header, RespositoryInfo, Issues } from './styles';
11	
12	interface Repository {
13	  full_name: string;
14	  description: string;
15	  owner: {
16	    login: string;
17	    avatar_url: string;
18	  };
19	  stargazers_count: number;
20	  forks_count: number;
21	  open_issues_count: number;
22	}
23	interface Issue {
24	  id: number;
25	  title: string;
26	  html_url: string;
27	  user: {
28	    login: string;
29	  };
30	}
