32	interface PullRequest {
33	  id: number;
34	  title: string;
35	  html_url: string;
36	  user: {
37	    login: string;
38	  };
39	  created_at: string;
40	}
41	
42	const Repository: React.FC = () => {
43	  const { '*': repositoryName } = useParams();
44	  const [repository, setRepository] = useState<Repository | null>(null);
45	  const [issues, setIssues] = useState<Issue[]>([]);
46	  const [pulls, setPulls] = useState<PullRequest[]>([]);
47	  const [activeTab, setActiveTab] = useState<'issues' | 'pulls'>('issues');
48	
49	  useEffect(() => {
50	    api.get(`/repos/${repositoryName}`).then((response) => {
51	      setRepository(response.data);
52	    });
53	    api.get(`/repos/${repositoryName}/issues`).then((response) => {
54	      setIssues(response.data);
55	    });
56	    api.get(`/repos/${repositoryName}/pulls?state=open`).then((response) => {
57	      setPulls(response.data);
58	    });
59	  }, [repositoryName]);
60	
61	  return (
62	    <>
63	      <Header>
64	        <img src={logoImage} alt="Github Explorer" />
65	        <Link to="/">
66	          <FiChevronLeft size={16} color="#3D3D4D" />
67	          <strong>Voltar</strong>
68	        </Link>
69	      </Header>
70	      {repository ? (
71	        <RespositoryInfo>
72	          <header>
73	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
74	            <div>
75	              <strong>{repository.full_name}</strong>
76	              <p>{repository.description}</p>
77	            </div>
78	          </header>
79	          <ul>
80	            <li>
81	              <strong>{repository.stargazers_count}</strong>
82	              <span>Stars</span>
83	            </li>
84	            <li>
85	              <strong>{repository.forks_count}</strong>
86	              <span>Forks</span>
87	            </li>
88	            <li>
89	              <strong>{repository.open_issues_count}</strong>
90	              <span>Issues abertos</span>
91	            </li>
92	          </ul>
93	        </RespositoryInfo>
94	      ) : (
95	        <p>Carregando informações.</p>
96	      )}
97	
98	      <Tabs>
99	        <Tab isActive={activeTab === 'issues'} onClick={() => setActiveTab('issues')}>
100	          Issues ({issues.length})
101	        </Tab>
102	        <Tab isActive={activeTab === 'pulls'} onClick={() => setActiveTab('pulls')}>
103	          Pull Requests ({pulls.length})
104	        </Tab>
105	      </Tabs>
106	
107	      <Issues>
108	        {activeTab === 'issues' &&
109	          issues.map((issue) => (
110	            <a key={issue.id} href={issue.html_url}>
111	              <div>
112	                <strong>{issue.title}</strong>
113	                <p>{issue.user.login}</p>
114	              </div>
115	              <FiChevronRight size={20} />
116	            </a>
117	          ))}
118	        {activeTab === 'pulls' &&
119	          pulls.map((pull) => (
120	            <a key={pull.id} href={pull.html_url}>
121	              <div>
122	                <strong>{pull.title}</strong>
123	                <p>{pull.user.login}</p>
124	              </div>
125	              <FiChevronRight size={20} />
126	            </a>
127	          ))}
128	      </Issues>
129	
130	      <Footer />
131	    </>
132	  );
133	};
134	
135	export default Repository;
